// ─── File: pages/TransferPage.ts ───
import { Page, Locator } from '@playwright/test';

export class TransferPage {
  readonly page: Page;

  // (Avoid) BRITTLE (do NOT do this): tied to generated IDs/classes.
  //   page.locator('#input-9f3a2');
  //   page.locator('div.css-1x7yz > button:nth-child(3)');

  // (Recommended) STABLE: user-facing, accessibility-based locators.
  readonly fromAccount: Locator;
  readonly toAccount: Locator;
  readonly amount: Locator;
  readonly submit: Locator;
  readonly successBanner: Locator;

  constructor(page: Page) {
    this.page = page;
    this.fromAccount = page.getByLabel('From account');      // by label
    this.toAccount = page.getByLabel('To account');          // by label
    this.amount = page.getByLabel('Amount');                 // by label
    this.submit = page.getByRole('button', { name: 'Transfer' }); // by role+name
    this.successBanner = page.getByRole('alert');            // by role
  }

  async goto() { await this.page.goto('/transfer'); }

  async makeTransfer(from: string, to: string, amount: string) {
    await this.fromAccount.selectOption(from);
    await this.toAccount.fill(to);
    await this.amount.fill(amount);
    await this.submit.click();
  }

  // Scoped, stable locator: find the row by its visible account text,
  // then the action button INSIDE that row (no dynamic IDs involved).
  rowActionFor(accountText: string): Locator {
    return this.page
      .getByRole('row', { name: new RegExp(accountText, 'i') })
      .getByRole('button', { name: 'View' });
  }

  // Where no good user-facing handle exists, use an explicit testId
  // that developers agree not to change (a test contract).
  statementLink(): Locator {
    return this.page.getByTestId('download-statement');
  }
}
