// ─── File: tests/transfer.spec.ts ───
import { test, expect } from '@playwright/test';
import { TransferPage } from '../pages/TransferPage';

test.describe('Stable locators on transfer screen', () => {
  test('transfer uses role/label locators, not generated IDs', async ({ page }) => {
    const transfer = new TransferPage(page);
    await transfer.goto();

    // These keep working even if the app regenerates IDs/classes on each build.
    await transfer.makeTransfer('SAV2001', 'CUR3001', '50000');

    // Assert by role, with auto-waiting; stable across refactors.
    await expect(transfer.successBanner).toContainText(/transfer.*completed/i);
  });

  test('scoped row locator finds the right action by content', async ({ page }) => {
    const transfer = new TransferPage(page);
    await transfer.goto();

    // Locate the CUR3001 row by text, then its View button — no nth-child.
    await transfer.rowActionFor('CUR3001').click();
    await expect(page.getByRole('heading', { name: /account cur3001/i })).toBeVisible();
  });

  test('testId fallback for elements without user-facing handles', async ({ page }) => {
    const transfer = new TransferPage(page);
    await transfer.goto();
    await expect(transfer.statementLink()).toBeVisible();
  });
});
